get_customer_portal.code:
var response = await client.CustomerPortal.GetCustomerPortalAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var customerPortal = (IReadOnlyDictionary<string, object?>)body["customer_portal"]!;
var login = (IReadOnlyDictionary<string, object?>)customerPortal["login"]!;
Console.WriteLine($"{login["enabled"]} {login["registration_link"]}");

patch_customer_portal.code:
var response = await client.CustomerPortal.PatchCustomerPortalAsync(new Dictionary<string, object?>
{
    ["customer_portal"] = new Dictionary<string, object?>
    {
        ["login"] = new Dictionary<string, object?> { ["registration_link"] = false },
        ["sso"] = new Dictionary<string, object?> { ["azure_ad"] = new Dictionary<string, object?> { ["data_mapping"] = new Dictionary<string, object?> { ["city"] = "city" } } },
    },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var customerPortal = (IReadOnlyDictionary<string, object?>)body["customer_portal"]!;
var login = (IReadOnlyDictionary<string, object?>)customerPortal["login"]!;
Console.WriteLine(login["registration_link"]);

